package com.supportsphere.dao;
import com.supportsphere.model.*; import com.supportsphere.util.*; import java.sql.*; import java.util.*;
public class UserDAO implements DAO<User,Integer>{
 public int register(String name,String email,String password,String phone,Role role,String area,String city,String landmark,String notes,int exp,Time start,Time end,List<String> skills) throws Exception{
  try(Connection c=DBConnection.getConnection()){c.setAutoCommit(false); try{String q="INSERT INTO users(name,email,password,phone,role,area,city,landmark) VALUES(?,?,?,?,?,?,?,?)"; int id; try(PreparedStatement p=c.prepareStatement(q,Statement.RETURN_GENERATED_KEYS)){p.setString(1,name);p.setString(2,email);p.setString(3,PasswordUtil.sha256(password));p.setString(4,phone);p.setString(5,role.name());p.setString(6,area);p.setString(7,city);p.setString(8,landmark);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();id=r.getInt(1);}}
   if(role==Role.REQUESTER){try(PreparedStatement p=c.prepareStatement("INSERT INTO requester_profiles(requester_id,accessibility_notes) VALUES(?,?)")){p.setInt(1,id);p.setString(2,notes);p.executeUpdate();}}
   if(role==Role.VOLUNTEER){try(PreparedStatement p=c.prepareStatement("INSERT INTO volunteer_profiles(volunteer_id,experience_years,availability_start,availability_end) VALUES(?,?,?,?)")){p.setInt(1,id);p.setInt(2,exp);p.setTime(3,start);p.setTime(4,end);p.executeUpdate();} for(String s:skills){int sid; try(PreparedStatement p=c.prepareStatement("INSERT INTO skills(skill_name) VALUES(?) ON DUPLICATE KEY UPDATE skill_id=LAST_INSERT_ID(skill_id)",Statement.RETURN_GENERATED_KEYS)){p.setString(1,s);p.executeUpdate();try(ResultSet r=p.getGeneratedKeys()){r.next();sid=r.getInt(1);}} try(PreparedStatement p=c.prepareStatement("INSERT IGNORE INTO volunteer_skills(volunteer_id,skill_id) VALUES(?,?)")){p.setInt(1,id);p.setInt(2,sid);p.executeUpdate();}}}
   c.commit();return id;}catch(Exception e){c.rollback();throw e;}}
 }
 public Optional<User> authenticate(String email,String password) throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE email=? AND password=? AND status='ACTIVE'")){p.setString(1,email);p.setString(2,PasswordUtil.sha256(password));try(ResultSet r=p.executeQuery()){if(!r.next())return Optional.empty();return Optional.of(map(r));}}}
 public Optional<User> findById(Integer id)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM users WHERE user_id=?")){p.setInt(1,id);try(ResultSet r=p.executeQuery()){return r.next()?Optional.of(map(r)):Optional.empty();}}}
 public List<User> findAll()throws Exception{List<User>x=new ArrayList<>();try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("SELECT * FROM users ORDER BY created_at DESC");ResultSet r=p.executeQuery()){while(r.next())x.add(map(r));}return x;}
 public void setStatus(int id,String status)throws Exception{try(Connection c=DBConnection.getConnection();PreparedStatement p=c.prepareStatement("UPDATE users SET status=? WHERE user_id=?")){p.setString(1,status);p.setInt(2,id);p.executeUpdate();}}
 private User map(ResultSet r)throws Exception{int id=r.getInt("user_id");String n=r.getString("name"),e=r.getString("email"),ph=r.getString("phone"),a=r.getString("area"),city=r.getString("city"),l=r.getString("landmark");Role role=Role.valueOf(r.getString("role"));User user=switch(role){case REQUESTER->new Requester(id,n,e,ph,a,city,l);case VOLUNTEER->new Volunteer(id,n,e,ph,a,city,l);case ADMIN->new Admin(id,n,e,ph,a,city,l);};user.setStatus(r.getString("status"));return user;}
}
